import type { Metadata } from "next";

// browse/page.tsx is a Client Component (it reads useSearchParams for live
// filtering), and metadata exports only work in Server Components — so the
// metadata lives here instead, in the route's server-rendered layout.
export const metadata: Metadata = {
  title: "Browse",
  description:
    "Browse the full verified archive of Florida Man stories — filter by category, city, date, and Florida Man score.",
  alternates: { canonical: "/browse" },
};

export default function BrowseLayout({ children }: LayoutProps<"/browse">) {
  return children;
}

"use client";

import { Suspense, useMemo, useState } from "react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import Header from "../components/Header";
import { stories } from "../data/stories";
import { StoryVisual, getScoreColor } from "../components/StoryVisual";
import { getStoryTimestamp, MONTH_NAMES } from "../lib/storyDate";
import { getAnimalStories } from "../lib/animalStories";
import React from "react";

const SCORE_FILTERS = ["Any score", "90+ Florida Man", "80+ Florida Man", "65+ Florida Man"];
const DAY_OPTIONS = Array.from({ length: 31 }, (_, i) => String(i + 1));

const SELECT_CLASSES =
  "rounded-xl border border-line bg-white p-3 text-sm font-medium text-ink focus:outline-none focus:ring-2 focus:ring-sunset/40";

// A single <select> filter styled consistently with the others. Adding a
// new filter to the toolbar is now "define its options, render one of
// these" instead of copy-pasting a whole <select> block.
function FilterSelect({
  value,
  onChange,
  placeholder,
  options,
}: {
  value: string;
  onChange: (value: string) => void;
  placeholder: string;
  options: string[];
}) {
  return (
    <select
      value={value}
      onChange={(e) => onChange(e.target.value)}
      className={SELECT_CLASSES}
    >
      <option>{placeholder}</option>
      {options.map((option) => (
        <option key={option}>{option}</option>
      ))}
    </select>
  );
}

const SORT_OPTIONS = {
  "Newest first": (a: (typeof stories)[number], b: (typeof stories)[number]) =>
    getStoryTimestamp(b) - getStoryTimestamp(a),
  "Oldest first": (a: (typeof stories)[number], b: (typeof stories)[number]) =>
    getStoryTimestamp(a) - getStoryTimestamp(b),
  "Score: high to low": (a: (typeof stories)[number], b: (typeof stories)[number]) =>
    b.score - a.score,
  "Score: low to high": (a: (typeof stories)[number], b: (typeof stories)[number]) =>
    a.score - b.score,
} as const;

type SortOption = keyof typeof SORT_OPTIONS;

function BrowseContent() {
  // Pick up a category filter passed in from the homepage chips (?search=gator
  // or ?category=animals)
  const searchParams = useSearchParams();
  const category = searchParams.get("category");
  const [search, setSearch] = useState(() => searchParams.get("search") ?? "");
  const [year, setYear] = useState("All years");
  const [month, setMonth] = useState("All months");
  const [day, setDay] = useState("All days");
  const [city, setCity] = useState("All cities");
  const [score, setScore] = useState("Any score");
  const [sort, setSort] = useState<SortOption>("Newest first");

  const basePool = useMemo(
    () => (category === "animals" ? getAnimalStories(stories) : stories),
    [category]
  );

  const years = useMemo(
    () => Array.from(new Set(basePool.map((story) => story.year))).sort(
      (a, b) => Number(b) - Number(a)
    ),
    [basePool]
  );

  const cities = useMemo(
    () => Array.from(new Set(basePool.map((story) => story.city))).sort(),
    [basePool]
  );

  // Memoized so filtering/sorting only reruns when a filter or the pool
  // actually changes, rather than on every render (e.g. while another part
  // of the page re-renders) — matters more as the archive keeps growing.
  const filteredStories = useMemo(
    () =>
      basePool
        .filter((story) => {
          const term = search.toLowerCase();

          const searchMatch =
            search === "" ||
            story.title.toLowerCase().includes(term) ||
            story.city.toLowerCase().includes(term) ||
            story.description.toLowerCase().includes(term);

          const yearMatch = year === "All years" || story.year === year;
          const monthMatch = month === "All months" || story.month === month;
          const dayMatch = day === "All days" || story.day === day;
          const cityMatch = city === "All cities" || story.city === city;

          let scoreMatch = true;

          if (score === "90+ Florida Man") {
            scoreMatch = story.score >= 90;
          } else if (score === "80+ Florida Man") {
            scoreMatch = story.score >= 80;
          } else if (score === "65+ Florida Man") {
            scoreMatch = story.score >= 65;
          }

          return (
            searchMatch &&
            yearMatch &&
            monthMatch &&
            dayMatch &&
            cityMatch &&
            scoreMatch
          );
        })
        .sort(SORT_OPTIONS[sort]),
    [basePool, search, year, month, day, city, score, sort]
  );

  const filtersActive =
    search ||
    year !== "All years" ||
    month !== "All months" ||
    day !== "All days" ||
    city !== "All cities" ||
    score !== "Any score";

  return (
    <main className="min-h-screen bg-paper text-ink">
      <Header />

      <section className="mx-auto max-w-6xl px-6 py-12">
        <p className="text-sm font-medium text-flamingo">Florida Man archive</p>

        <h2 className="mt-2 text-5xl font-bold tracking-tight md:text-6xl">
          {category === "animals" ? "Animal stories" : "Browse"}
        </h2>

        {category === "animals" && (
          <div className="mt-4 flex flex-wrap items-center gap-3">
            <span className="rounded-full bg-citrus/25 px-3 py-1 text-sm font-medium text-ink">
              🐾 Filtered to animal stories
            </span>

            <Link
              href="/browse"
              className="text-sm font-medium text-sunset hover:text-sunset-dark"
            >
              Clear category →
            </Link>
          </div>
        )}

        <div className="mt-10 rounded-2xl bg-white p-5 shadow-md shadow-ink/5 ring-1 ring-line">
          <div className="grid gap-3 md:grid-cols-6">
            <input
              type="text"
              placeholder="Search stories..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="rounded-xl border border-line bg-white p-3 text-sm font-medium placeholder:text-ink-soft/70 focus:outline-none focus:ring-2 focus:ring-sunset/40"
            />

            <FilterSelect value={year} onChange={setYear} placeholder="All years" options={years} />
            <FilterSelect value={month} onChange={setMonth} placeholder="All months" options={MONTH_NAMES} />
            <FilterSelect value={day} onChange={setDay} placeholder="All days" options={DAY_OPTIONS} />
            <FilterSelect value={city} onChange={setCity} placeholder="All cities" options={cities} />
            <FilterSelect value={score} onChange={setScore} placeholder="Any score" options={SCORE_FILTERS.slice(1)} />
          </div>

          <div className="mt-4 flex flex-wrap items-center justify-between gap-4 border-t border-line pt-4">
            <p className="text-sm text-ink-soft">
              {filteredStories.length} of {basePool.length} stories
            </p>

            <div className="flex items-center gap-3">
              <label className="text-sm text-ink-soft">Sort</label>

              <select
                value={sort}
                onChange={(e) => setSort(e.target.value as SortOption)}
                className="rounded-xl border border-line bg-white p-2 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-sunset/40"
              >
                {Object.keys(SORT_OPTIONS).map((option) => (
                  <option key={option}>{option}</option>
                ))}
              </select>

              {filtersActive && (
                <button
                  onClick={() => {
                    setSearch("");
                    setYear("All years");
                    setMonth("All months");
                    setDay("All days");
                    setCity("All cities");
                    setScore("Any score");
                  }}
                  className="rounded-full bg-citrus/25 px-3.5 py-2 text-sm font-medium text-ink transition-colors hover:bg-citrus/40"
                >
                  Clear filters
                </button>
              )}
            </div>
          </div>
        </div>

        <div className="mt-6 divide-y divide-line rounded-2xl bg-white shadow-md shadow-ink/5 ring-1 ring-line">
          {filteredStories.length === 0 ? (
            <p className="px-6 py-14 text-center font-medium text-ink-soft">
              No Florida Man stories found.
            </p>
          ) : (
            filteredStories.map((story) => (
              <Link
                href={`/story/${story.id}`}
                key={story.id}
                className="flex items-center gap-5 px-5 py-5 transition-colors hover:bg-paper-soft"
              >
                <StoryVisual story={story} size="sm" />

                <div className="flex-1">
                  <p className="text-sm font-medium text-flamingo">
                    {story.date} · {story.city}
                  </p>

                  <h3 className="mt-1.5 text-xl font-semibold leading-tight">
                    {story.contentNote && (
                      <span title="Content note">⚠️ </span>
                    )}
                    {story.title}
                  </h3>
                </div>

                <div className="text-right">
                  <p className="text-xs font-medium text-ink-soft">Score</p>

                  <p
                    className="text-2xl font-bold"
                    style={{ color: getScoreColor(story.score) }}
                  >
                    {story.score}
                  </p>
                </div>
              </Link>
            ))
          )}
        </div>
      </section>
    </main>
  );
}

export default function Browse() {
  return (
    <Suspense fallback={<main className="min-h-screen bg-paper" />}>
      <BrowseContent />
    </Suspense>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import Header from "../components/Header";
import { stories, type Story } from "../data/stories";
import { StoryVisual, getScoreColor } from "../components/StoryVisual";
import { getMonthDayOrder } from "../lib/storyDate";
import React from "react";

export const metadata: Metadata = {
  title: "Calendar",
  description:
    "A day-by-day calendar of verified Florida Man incidents — see which absurd story won each day in Florida Man history.",
  alternates: { canonical: "/calendar" },
};

export default function Calendar() {
  // Group by calendar day (month + day), ignoring year, so every real day
  // in Florida Man history gets exactly one "of the day" winner. Stories
  // without a specific day on record (year only) can't win a day, so they're
  // excluded rather than guessed at.
  const storiesByDay = new Map<string, Story[]>();

  for (const story of stories) {
    if (!story.month || !story.day) continue;

    const key = `${story.month}-${story.day}`;
    const group = storiesByDay.get(key);

    if (group) {
      group.push(story);
    } else {
      storiesByDay.set(key, [story]);
    }
  }

  const days = Array.from(storiesByDay.values())
    .map((storiesForDay) =>
      storiesForDay.reduce((highest, story) =>
        story.score > highest.score ? story : highest
      )
    )
    .sort((a, b) => getMonthDayOrder(a) - getMonthDayOrder(b))

  return (
    <main className="min-h-screen bg-paper text-ink">
      <Header />

      <section className="mx-auto max-w-6xl px-6 py-12">
        <p className="text-sm font-medium text-flamingo">Daily archive</p>

        <h2 className="mt-2 text-5xl font-bold tracking-tight md:text-6xl">
          Calendar
        </h2>

        <p className="mt-5 max-w-2xl text-ink-soft">
          Every day gets one Florida Man of the Day. Browse the archive and
          see which story won.
        </p>

        <div className="mt-10 divide-y divide-line rounded-2xl bg-white shadow-md shadow-ink/5 ring-1 ring-line">
          {days.map((day) => (
            <Link
              href={`/story/${day.id}`}
              key={day.id}
              className="flex items-center gap-5 px-5 py-5 transition-colors hover:bg-paper-soft"
            >
              <StoryVisual story={day} size="sm" />

              <div className="flex-1">
                <p className="text-sm font-medium text-flamingo">{day.date}</p>

                <h3 className="mt-1.5 text-xl font-semibold leading-tight">
                  {day.contentNote && <span title="Content note">⚠️ </span>}
                  {day.title}
                </h3>

                <p className="mt-1.5 text-sm text-ink-soft">
                  {day.city}, Florida
                </p>
              </div>

              <div className="text-right">
                <p className="text-xs font-medium text-ink-soft">Score</p>

                <p
                  className="text-2xl font-bold"
                  style={{ color: getScoreColor(day.score) }}
                >
                  {day.score}
                </p>
              </div>
            </Link>
          ))}
        </div>
      </section>
    </main>
  )
}

import Image from "next/image";

type Tile = {
  url: string;
  rotate: string;
  credit: string;
};

const LEFT_TILES: Tile[] = [
  {
    url: "https://upload.wikimedia.org/wikipedia/commons/0/03/American_Alligator.jpg",
    rotate: "-rotate-2",
    credit: "Postdlf (CC BY-SA 3.0)",
  },
  {
    url: "https://upload.wikimedia.org/wikipedia/commons/7/72/American_flamingo_%28Phoenicopterus_ruber%29.JPG",
    rotate: "rotate-1",
    credit: "Charles J. Sharp (CC BY-SA 4.0)",
  },
];

const RIGHT_TILES: Tile[] = [
  {
    url: "https://upload.wikimedia.org/wikipedia/commons/6/6b/Palm_Coast_Sunset.jpg",
    rotate: "rotate-2",
    credit: "Andyrkellergmail (CC BY-SA 4.0)",
  },
  {
    url: "https://upload.wikimedia.org/wikipedia/commons/8/83/Everglades_swamp.JPG",
    rotate: "-rotate-1",
    credit: "Hein Mück (CC BY-SA 3.0)",
  },
];

// Decorative real-Florida photo strip pinned to the viewport edge on very
// wide screens only — purely visual flavor, never overlaps main content.
export function FloridaRail({ side }: { side: "left" | "right" }) {
  const tiles = side === "left" ? LEFT_TILES : RIGHT_TILES;

  return (
    <div
      aria-hidden="true"
      className={`pointer-events-none fixed top-1/4 z-0 hidden 2xl:flex 2xl:flex-col 2xl:gap-6 ${
        side === "left" ? "left-8" : "right-8"
      }`}
    >
      {tiles.map((tile) => (
        <div
          key={tile.url}
          className={`relative h-28 w-24 overflow-hidden rounded-2xl bg-white shadow-lg shadow-ink/10 ring-1 ring-ink/5 ${tile.rotate}`}
        >
          <Image
            src={tile.url}
            alt=""
            fill
            sizes="96px"
            className="object-cover"
          />
        </div>
      ))}
    </div>
  );
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import React from "react";

const NAV_LINKS = [
  { href: "/", label: "Today" },
  { href: "/browse", label: "Browse" },
  { href: "/calendar", label: "Calendar" },
  { href: "/about", label: "About" },
];

export default function Header() {
  const pathname = usePathname();

  return (
    <header className="sticky top-0 z-40 border-b border-line bg-paper/85 backdrop-blur-md">
      <div className="mx-auto flex max-w-6xl items-center justify-between gap-4 px-6 py-4">
        <Link href="/" className="flex items-center gap-2.5">
          <span className="text-2xl">🐊</span>
          <span>
            <span className="block text-lg font-semibold tracking-tight text-ink">
              Florida Man
            </span>
            <span className="block text-xs text-ink-soft">
              The daily archive of Florida
            </span>
          </span>
        </Link>

        <nav className="flex items-center gap-1 text-sm font-medium">
          {NAV_LINKS.map((link) => {
            const active = pathname === link.href;

            return (
              <Link
                key={link.href}
                href={link.href}
                className={`rounded-full px-3.5 py-2 transition-colors ${
                  active
                    ? "bg-sunset/10 text-sunset-dark"
                    : "text-ink-soft hover:bg-ink/5 hover:text-ink"
                }`}
              >
                {link.label}
              </Link>
            );
          })}
        </nav>
      </div>
    </header>
  );
}

import Image from "next/image";
import type { Story } from "../data/stories";

type Photo = {
  url: string;
  credit: string;
};

type Category = {
  test: RegExp;
  emoji: string;
  label: string;
  gradient: string;
  photo?: Photo;
};

// Real, CC-licensed photos from Wikimedia Commons — generic scene photography
// (gators, cruisers, coastline) rather than mugshots of the real people
// involved, since those aren't ours to republish.
const CATEGORIES: Category[] = [
  {
    test: /\balligators?\b|\bgators?\b|\bcrocs?\b|crocodile/i,
    emoji: "🐊",
    label: "Gator alert",
    gradient: "from-[#0B8F7E] to-[#14C2A8]",
    photo: {
      url: "https://upload.wikimedia.org/wikipedia/commons/0/03/American_Alligator.jpg",
      credit: "Postdlf / Wikimedia Commons (CC BY-SA 3.0)",
    },
  },
  {
    test: /horse|snake|hamster wheel/i,
    emoji: "🐴",
    label: "Wild animal",
    gradient: "from-[#A9782F] to-[#E3A93F]",
    photo: {
      url: "https://upload.wikimedia.org/wikipedia/commons/3/38/Horse3.jpg",
      credit: "Joshua Ganderson / Wikimedia Commons (CC BY 2.0)",
    },
  },
  {
    test: /spider-?man|bunny|tutu|mask|costume/i,
    emoji: "🎭",
    label: "Costume chaos",
    gradient: "from-[#8B5CF6] to-[#EF3F7B]",
    photo: {
      url: "https://upload.wikimedia.org/wikipedia/commons/2/2d/Carnival_mask.jpg",
      credit: "Heterotrofo / Wikimedia Commons (CC0)",
    },
  },
  { test: /naked|nude|prosthetic/i, emoji: "🍑", label: "Bare necessities", gradient: "from-[#EF3F7B] to-[#FFBE3D]" },
  {
    test: /gun|machete|knife|armed|weapon/i,
    emoji: "🔪",
    label: "Armed & alarming",
    gradient: "from-[#C81E3A] to-[#FF5A36]",
    photo: {
      url: "https://upload.wikimedia.org/wikipedia/commons/1/12/Handcuffs_1.jpg",
      credit: "SimmeD / Wikimedia Commons (CC BY-SA 4.0)",
    },
  },
  { test: /\bmeth\b|marijuana|\bdrugs?\b|clonazepam/i, emoji: "💊", label: "Substance situation", gradient: "from-[#6D28D9] to-[#9333EA]" },
  { test: /lawn mower|scooter|helicopter|\btrucks?\b|\bmph\b|\bcars?\b|vehicle/i, emoji: "🚗", label: "Vehicular villainy", gradient: "from-[#FF5A36] to-[#FFBE3D]" },
  {
    test: /steal\w*|stolen|theft|burglary|\brob\w*|\bcoins?\b|avocado/i,
    emoji: "💰",
    label: "Petty heist",
    gradient: "from-[#FFBE3D] to-[#FF8A3D]",
    photo: {
      url: "https://upload.wikimedia.org/wikipedia/commons/8/83/Shopping_cart.jpg",
      credit: "Guanaco / Wikimedia Commons (CC0)",
    },
  },
  {
    test: /police|officers?|deput\w*|\bcops?\b|\b911\b|bomb|carjack/i,
    emoji: "🚨",
    label: "Cop trouble",
    gradient: "from-[#2563EB] to-[#EF3F7B]",
    photo: {
      url: "https://upload.wikimedia.org/wikipedia/commons/e/e6/Police_car_with_emergency_lights_on.jpg",
      credit: "Scott Davidson / Wikimedia Commons (CC BY 2.0)",
    },
  },
  {
    test: /ocean|atlantic|boat|water/i,
    emoji: "🌊",
    label: "High seas",
    gradient: "from-[#0EA5C7] to-[#0FA895]",
    photo: {
      url: "https://upload.wikimedia.org/wikipedia/commons/3/3a/Sunset_on_coast_of_Florida.jpg",
      credit: "Don Miller / Wikimedia Commons (CC BY 2.0)",
    },
  },
];

const DEFAULT_CATEGORY: Category = {
  test: /.*/,
  emoji: "🌴",
  label: "Florida Man",
  gradient: "from-[#FF5A36] to-[#EF3F7B]",
  photo: {
    url: "https://upload.wikimedia.org/wikipedia/commons/6/6b/Palm_Coast_Sunset.jpg",
    credit: "Andyrkellergmail / Wikimedia Commons (CC BY-SA 4.0)",
  },
};

type StoryLike = Pick<Story, "title" | "description" | "fullStory">;

export function getStoryVisual(story: StoryLike) {
  const text = `${story.title} ${story.description} ${story.fullStory}`;
  return CATEGORIES.find((category) => category.test.test(text)) ?? DEFAULT_CATEGORY;
}

// Score is out of 100 — the literal sum of a story's six rubric categories.
export function getScoreColor(score: number) {
  if (score >= 90) return "#EF3F7B";
  if (score >= 80) return "#FF5A36";
  if (score >= 65) return "#FFBE3D";
  if (score >= 50) return "#0FA895";
  return "#9AA1A8";
}

export function getScoreTextColor(score: number) {
  return score >= 65 && score < 80 ? "#17191c" : "#ffffff";
}

export function getScoreLabel(score: number) {
  if (score >= 90) return "Legendary";
  if (score >= 80) return "Certified wild";
  if (score >= 65) return "Pretty wild";
  if (score >= 50) return "Classic Florida";
  return "Not actually funny";
}

// The circular score + rating readout shown on both the homepage feature
// card and the story page. Pulled out once so score styling only has one
// place to change, and any future page (browse cards, calendar) can reuse
// it instead of re-deriving the same markup.
export function ScoreBadge({
  score,
  label = "Florida Man score",
  shrink = false,
}: {
  score: number;
  label?: string;
  shrink?: boolean;
}) {
  return (
    <div className="flex items-center gap-4">
      <div
        className={`flex h-20 w-20 flex-col items-center justify-center rounded-full shadow-lg shadow-ink/10 ring-4 ring-paper ${
          shrink ? "shrink-0" : ""
        }`}
        style={{ backgroundColor: getScoreColor(score) }}
      >
        <p
          className="text-2xl font-bold leading-none"
          style={{ color: getScoreTextColor(score) }}
        >
          {score}
        </p>
        <p
          className="text-[10px] font-medium opacity-80"
          style={{ color: getScoreTextColor(score) }}
        >
          / 100
        </p>
      </div>

      <div>
        <p className="text-sm font-medium text-ink-soft">{label}</p>
        <p className="font-semibold text-ink">{getScoreLabel(score)}</p>
      </div>
    </div>
  );
}

const SIZES = {
  sm: { box: "h-16 w-16 rounded-xl", emoji: "text-3xl", label: false, credit: false },
  md: { box: "aspect-square w-full rounded-2xl", emoji: "text-6xl", label: true, credit: false },
  lg: { box: "aspect-[4/3] w-full rounded-3xl", emoji: "text-8xl", label: true, credit: true },
} as const;

export function StoryVisual({
  story,
  size = "md",
}: {
  story: StoryLike;
  size?: keyof typeof SIZES;
}) {
  const visual = getStoryVisual(story);
  const sizing = SIZES[size];

  return (
    <div
      className={`relative flex ${sizing.box} shrink-0 items-center justify-center overflow-hidden bg-gradient-to-br shadow-md shadow-ink/10 ring-1 ring-ink/5 ${visual.gradient}`}
    >
      {visual.photo ? (
        <>
          <Image
            src={visual.photo.url}
            alt=""
            aria-hidden="true"
            fill
            sizes="(max-width: 768px) 100vw, 400px"
            className="object-cover"
          />
          <div
            className={`absolute inset-0 bg-gradient-to-br opacity-35 ${visual.gradient}`}
          />
        </>
      ) : (
        <span className={`relative ${sizing.emoji} drop-shadow-[0_2px_6px_rgba(0,0,0,0.25)]`}>
          {visual.emoji}
        </span>
      )}

      {sizing.label && (
        <span className="absolute bottom-2 left-2 rounded-full bg-ink/70 px-2.5 py-1 text-[11px] font-medium text-white backdrop-blur-sm">
          {visual.label}
