import type { Story } from "../data/stories";

const MONTHS: Record<string, number> = {
  January: 0,
  February: 1,
  March: 2,
  April: 3,
  May: 4,
  June: 5,
  July: 6,
  August: 7,
  September: 8,
  October: 9,
  November: 10,
  December: 11,
};

// Calendar-ordered month names, derived from the same map above so any page
// that needs a month list (e.g. a filter dropdown) can't drift out of sync
// with the values `getStoryTimestamp`/`getMonthDayOrder` actually recognize.
export const MONTH_NAMES = Object.keys(MONTHS);

// Story dates are stored as separate, sometimes-incomplete year/month/day
// text fields (some older stories only have a year). This resolves them to
// a sortable timestamp, defaulting missing month/day to the start of the
// period so imprecise dates still sort sensibly relative to precise ones.
export function getStoryTimestamp(story: Pick<Story, "year" | "month" | "day">) {
  const year = parseInt(story.year, 10) || 0;
  const month = MONTHS[story.month] ?? 0;
  const day = parseInt(story.day, 10) || 1;

  return new Date(year, month, day).getTime();
}

// Orders stories by calendar day (month + day) only, ignoring the year, so
// e.g. a Jan 5 story from 2016 sorts before an Aug 20 story from 2026.
export function getMonthDayOrder(story: Pick<Story, "month" | "day">) {
  const month = MONTHS[story.month] ?? 0;
  const day = parseInt(story.day, 10) || 1;

  return month * 100 + day;
}

import type { Story } from "../data/stories";

// Florida runs on Eastern time regardless of where this is hosted, so "today"
// is resolved there rather than the server's local timezone.
export function getFloridaToday() {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    year: "numeric",
    month: "long",
    day: "numeric",
  }).formatToParts(new Date());

  const map = Object.fromEntries(parts.map((p) => [p.type, p.value]));

  return {
    year: map.year,
    month: map.month,
    day: String(Number(map.day)), // strip any leading zero to match story.day
  };
}

export function getStoryOfTheDay(stories: Story[]) {
  const today = getFloridaToday();

  // A story that actually happened on this month/day, in any year —
  // "on this day in Florida Man history."
  const onThisDayMatches = stories.filter(
    (story) => story.month === today.month && story.day === today.day
  );

  if (onThisDayMatches.length > 0) {
    const winner = onThisDayMatches.reduce((best, story) =>
      story.score > best.score ? story : best
    );

    return {
      story: winner,
      isOnThisDay: true as const,
      others: onThisDayMatches.filter((story) => story.id !== winner.id),
      today,
    };
  }

  // No verified incident on record for this exact date yet — fall back to a
  // deterministic pick so the page still has a featured story, and it only
  // changes once a day (not on every request).
  const startOfYear = Date.UTC(Number(today.year), 0, 0);
  const now = new Date(
    `${today.month} ${today.day}, ${today.year} 12:00:00 UTC`
  );
  const dayOfYear = Math.floor((now.getTime() - startOfYear) / 86_400_000);
  const fallback = stories[dayOfYear % stories.length];

  return {
    story: fallback,
    isOnThisDay: false as const,
    others: [],
    today,
  };
}

